package io.lumine.mythic.lib.api.crafting.recipes;
import io.lumine.mythic.lib.api.crafting.ingredients.*; import io.lumine.mythic.lib.api.util.Ref; import java.util.*;
public abstract class MythicRecipe { private final String name; protected final ArrayList<MythicRecipeIngredient> ingredients; private boolean live; public MythicRecipe(String name,ArrayList<MythicRecipeIngredient> ingredients){this.name=Objects.requireNonNull(name);this.ingredients=new ArrayList<>(ingredients);} public MythicRecipe(String name,MythicRecipeIngredient... ingredients){this(name,new ArrayList<>(Arrays.asList(ingredients)));} public abstract void addIngredient(MythicRecipeIngredient ingredient); public ArrayList<MythicRecipeIngredient> getIngredients(){return new ArrayList<>(ingredients);} public void clearIngredients(){ingredients.clear();} public String getName(){return name;} public abstract MythicRecipeStation getType(); public abstract MythicRecipeInventory matches(MythicRecipeInventory inventory,Ref<Integer> amount); public void load(){live=true;} public void unload(){live=false;} public boolean isLive(){return live;} }
